-- aether.nvim defaults floats/sidebars/popups to `dark_bg`, a derived gray
-- that isn't really part of the omarchy palette (very noticeable on light themes).
-- theme.lua is a symlink regenerated by omarchy, so overrides live here;
-- lazy.nvim merges these opts with the generated ones.
return {
  {
    "bjarneo/aether.nvim",
    opts = {
      styles = {
        floats = "normal",
        sidebars = "normal",
      },
      on_highlights = function(hl, c)
        hl.Pmenu = { bg = c.bg, fg = c.fg }
        hl.SnacksBackdrop = { bg = c.bg }
      end,
    },
  },
}
